              "skippable": {
                "mode": "script",
                "value": "(function execute() {\n    if(null!=vaInputs.badge_type && \"\"!=vaInputs.badge_type && vaVars.location_mobile_cred_enabled!=\"true\"){\n        return true;\n    }else{\n        return false;\n    }\n})()\n"
